CREATE TABLE meter_plans(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), asset_id TEXT NOT NULL REFERENCES assets(id), sensor_id TEXT NOT NULL REFERENCES sensors(id), owner_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN(0,1)), template TEXT NOT NULL, next_index INTEGER NOT NULL DEFAULT 0, last_sample_id TEXT REFERENCES telemetry(id), last_timestamp TEXT, last_raw REAL, offset REAL NOT NULL DEFAULT 0, total REAL, blocked_sample_id TEXT REFERENCES telemetry(id), last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE meter_plan_versions(plan_id TEXT NOT NULL REFERENCES meter_plans(id), version INTEGER NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, reason TEXT NOT NULL, template TEXT NOT NULL, enabled INTEGER NOT NULL, PRIMARY KEY(plan_id,version));
CREATE TABLE meter_occurrences(id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES meter_plans(id), occurrence_index INTEGER NOT NULL, threshold REAL NOT NULL, work_order_id TEXT NOT NULL UNIQUE REFERENCES work_orders(id), detected_at TEXT NOT NULL, overdue_at TEXT NOT NULL, plan_version INTEGER NOT NULL, UNIQUE(plan_id,occurrence_index));
CREATE TABLE meter_reconciliations(id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES meter_plans(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, sample_id TEXT NOT NULL REFERENCES telemetry(id), action TEXT NOT NULL, previous_total REAL, confirmed_total REAL NOT NULL, reason TEXT NOT NULL, version INTEGER NOT NULL);
